import{_ as a,a as r,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"C++ 与 C 库互操作：ABI 与句柄所有权","description":"将链接、不透明句柄、错误转换与 RAII 接管放在同一调用契约中。","frontmatter":{"title":"C++ 与 C 库互操作：ABI 与句柄所有权","description":"将链接、不透明句柄、错误转换与 RAII 接管放在同一调用契约中。","showdocs":{"topics":[{"id":"cpp","title":"C++","link":"/topics/cpp/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"C++ 原生边界：C ABI 与 RAII","summary":"将链接、不透明句柄、错误转换与 RAII 接管放在同一调用契约中。","status":"active","related":[{"title":"C++ 构建排错：头文件、包发现、配置与规模","link":"/programming/cpp/plus/troubleshooting/build-diagnostics","kind":"排错","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试","link":"/programming/cpp/plus/practice/spsc-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试 · SPSC测试怎样覆盖空满回绕和有序压力至一手资料与验证边界","link":"/programming/cpp/plus/practice/spsc-application-part-03","kind":"开发实践","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试 · SPSC完整工程怎样传输和校验消息","link":"/programming/cpp/plus/practice/spsc-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"C++ 完整 SPSC 实践：固定载荷、回绕与双线程测试 · SPSC完整项目的头文件入口测试怎样共享源码至SPSC示例怎样构建且区分预期与执行","link":"/programming/cpp/plus/practice/spsc-application-part-02","kind":"开发实践","scope":"general","audience":"general"}],"prev":{"text":"C++ 构建排错：头文件、包发现、配置与规模","link":"/programming/cpp/plus/troubleshooting/build-diagnostics"},"next":{"text":"C++ 完整实践：RAII 宿主连接 POSIX C 库","link":"/programming/cpp/plus/practice/abi-application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"C++ 构建排错：头文件、包发现、配置与规模","link":"/programming/cpp/plus/troubleshooting/build-diagnostics"},"next":{"text":"C++ 完整实践：RAII 宿主连接 POSIX C 库","link":"/programming/cpp/plus/practice/abi-application"}},"headers":[],"relativePath":"programming/cpp/native-interop.md","filePath":"programming/cpp/native-interop.md"}'),p={name:"programming/cpp/native-interop.md"};function o(i,e,l,s,c,h){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="c-与-c-库互操作-abi-与句柄所有权" tabindex="-1">C++ 与 C 库互操作：ABI 与句柄所有权 <a class="header-anchor" href="#c-与-c-库互操作-abi-与句柄所有权" aria-label="Permalink to &quot;C++ 与 C 库互操作：ABI 与句柄所有权&quot;">​</a></h1><h2 id="part-1" tabindex="-1">链接、不透明句柄与错误值 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;链接、不透明句柄与错误值 {#part-1}&quot;">​</a></h2><p>在<a href="/programming/cpp/base/basic/ownership-moves">对象生存期与移动</a>中，<code>unique_ptr</code> 使用与类型匹配的删除器。C 库创建的句柄必须交回库提供的销毁函数。本节对照<a href="/programming/cpp/plus/practice/abi-application#source">scan.h 与 main.cpp</a>，追踪第一次取得句柄到最后一次销毁的路径。</p><p>专题入口：<a href="#part-1">C++ C ABI 边界：链接、不透明句柄与错误值</a> · <a href="#part-2">C++ 原生资源所有权：接管、析构与借用</a> · <a href="/programming/cpp/plus/practice/abi-application">C++ 完整实践：RAII 宿主连接 POSIX C 库</a> · <a href="/programming/cpp/plus/troubleshooting/abi-diagnostics">C++ 原生边界排错：符号、释放器与异常政策</a></p><h3 id="part-1-linkage" tabindex="-1">C++调用C库为什么需要extern C <a class="header-anchor" href="#part-1-linkage" aria-label="Permalink to &quot;C++调用C库为什么需要extern C {#part-1-linkage}&quot;">​</a></h3><p>extern &quot;C&quot; 是语言链接声明，使 C++ 调用侧按相应链接约定引用 C 定义，避免默认 C++ 名称修饰造成符号不匹配。头文件用 __cplusplus 守卫，C 编译器不解析 C++ 语法；实现 scan.c 仍由 C 编译器处理。</p><p>不能把整个包含模板的 C++ 头文件塞进 C 链接块，也不能给同一个函数先声明 C++ 链接再换成 C 链接。语言链接本身不把类、std::string、异常或虚函数布局变成稳定公共协议。</p><h3 id="part-1-opaque" tabindex="-1">C++消费的不透明句柄隐藏了什么 <a class="header-anchor" href="#part-1-opaque" aria-label="Permalink to &quot;C++消费的不透明句柄隐藏了什么 {#part-1-opaque}&quot;">​</a></h3><p>公开 typedef struct scan scan 只让调用者持有指针，不让它依赖内部 mutex、路径数组或状态字段的布局。库可以修改实现结构而保持函数签名，但调用者不能 sizeof(scan)、栈上创建 scan 或自行访问字段。</p><p>不透明不等于任意二进制兼容。本项目静态库与宿主在同一工具链、架构和运行库约定下构建；跨版本发布还需要明确符号、调用约定、整数宽度、运行库及版本策略。这里只提供稳定边界的设计方法，不承诺跨编译器万能 ABI。</p><h3 id="part-1-errors" tabindex="-1">C++如何把C错误码转换成异常 <a class="header-anchor" href="#part-1-errors" aria-label="Permalink to &quot;C++如何把C错误码转换成异常 {#part-1-errors}&quot;">​</a></h3><p>check 接收0或正的 POSIX 错误编号，非零则抛 std::system_error，配 std::generic_category。它接收函数返回的 code，不去读 errno；否则 pthread 错误和清理之后的错误来源会被混淆。</p><p>异常只存在于 C++ 宿主侧，C 实现返回整数错误码。若未来库实现改成 C++，C 入口必须捕获全部异常并转成协议错误，不能允许异常穿过普通 C 调用栈。当前没有回调，不需要为不存在的回调建立额外框架。</p><h3 id="part-1-version" tabindex="-1">C++原生接口示例采用什么标准 <a class="header-anchor" href="#part-1-version" aria-label="Permalink to &quot;C++原生接口示例采用什么标准 {#part-1-version}&quot;">​</a></h3><p>宿主采用 C++20，库采用 C11，两端共享头文件。POSIX 文件与 pthread 接口要求系统提供相应开发环境，Windows 读者可在 WSL 中构建。CMake 最低版本为 3.20。</p><p>选择标准的目的是延续已有 C++20 课程并明确分离编译边界，不需要第三方 FFI 生成器。先掌握<a href="/programming/cpp/base/intermediate/foundations#raii">值语义与 RAII</a>，再阅读这一条 ABI 路线；C++ 入门不要求先完整学过 C，但阅读头文件需要认识指针、const 和错误返回协议。</p><h3 id="part-1-exercise" tabindex="-1">独立练习 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;独立练习 {#part-1-exercise}&quot;">​</a></h3><p>能否把std::string放进extern C接口就宣布ABI稳定？为什么不能在宿主sizeof(scan)？</p><details class="details custom-block"><summary>参考解答与检查条件</summary><p>不能；语言链接没有规定C++类布局与运行库兼容。scan是不完整类型，宿主不了解其布局，应由库创建销毁并通过函数访问。</p></details><h3 id="part-1-sources" tabindex="-1">资料与适用边界 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;资料与适用边界 {#part-1-sources}&quot;">​</a></h3><p>2026-10-17 核对 <a href="https://man7.org/linux/man-pages/man2/read.2.html" target="_blank" rel="noopener noreferrer">Linux read 手册</a>、<a href="https://man7.org/linux/man-pages/man2/write.2.html" target="_blank" rel="noopener noreferrer">write 手册</a>、<a href="https://man7.org/linux/man-pages/man2/close.2.html" target="_blank" rel="noopener noreferrer">close 的平台差异</a>、<a href="https://man7.org/linux/man-pages/man3/pthread_create.3.html" target="_blank" rel="noopener noreferrer">pthread_create</a>、<a href="https://man7.org/linux/man-pages/man3/pthread_join.3.html" target="_blank" rel="noopener noreferrer">pthread_join</a> 与 <a href="https://man7.org/linux/man-pages/man3/pthread_mutex_lock.3p.html" target="_blank" rel="noopener noreferrer">POSIX mutex 规范镜像</a>。Linux 手册中的实现差异不直接推广为 macOS 实测结果。工程由 <a href="https://cmake.org/cmake/help/v3.20/module/FindThreads.html" target="_blank" rel="noopener noreferrer">CMake FindThreads</a> 提供线程目标，构建期会检查平台需要哪些编译和链接设置。</p><p>C++ 链接与拥有关系参照 <a href="https://en.cppreference.com/w/cpp/language/language_linkage.html" target="_blank" rel="noopener noreferrer">cppreference language linkage</a>、<a href="https://en.cppreference.com/w/cpp/memory/unique_ptr.html" target="_blank" rel="noopener noreferrer">unique_ptr</a>；中文核对 <a href="https://learn.microsoft.com/zh-cn/cpp/cpp/extern-cpp?view=msvc-170" target="_blank" rel="noopener noreferrer">Microsoft extern 说明</a>，仅引用语言链接概念，不套用其 Windows 编译开关。文章采用独立组织的边界与失败推演，外链用于溯源，必要答案已在正文。</p><h2 id="part-2" tabindex="-1">接管、析构与借用 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;接管、析构与借用 {#part-2}&quot;">​</a></h2><p>先读前节句柄创建与错误返回协议，再沿<a href="/programming/cpp/plus/practice/abi-application#source">main.cpp 的 unique_ptr 接管路径</a>检查析构、借用和线程责任。</p><h3 id="part-2-adopt" tabindex="-1">C++什么时候应该接管C句柄 <a class="header-anchor" href="#part-2-adopt" aria-label="Permalink to &quot;C++什么时候应该接管C句柄 {#part-2-adopt}&quot;">​</a></h3><p>scan_create 成功后立即把 raw 交给带自定义删除器的 unique_ptr，删除器调用 scan_destroy，不能调用 delete 或 free。库拥有分配方式与内部资源清理顺序，宿主只拥有句柄的唯一销毁责任。</p><p>失败时 C 接口保证 out 为空，check 抛出不会遗失已交给调用方的资源；成功后接管使用无状态删除器，不包含额外可能失败的业务动作。若在接管前加入字符串分配或日志格式化，该步骤可能抛出并泄漏 raw，必须重新审查接管窗口。</p><h3 id="part-2-unwind" tabindex="-1">C++异常后C资源怎样释放 <a class="header-anchor" href="#part-2-unwind" aria-label="Permalink to &quot;C++异常后C资源怎样释放 {#part-2-unwind}&quot;">​</a></h3><p>run/report 的 check 抛出后，栈展开会调用 owner 的析构，再由删除器释放 C 句柄。删除器标 noexcept，不让清理异常覆盖原始错误；C 的 destroy 为 void 且不抛异常。构造尚未完成的对象不适用“对象析构会补救一切”，所以资源必须尽早交给已完成构造的 RAII 拥有者。</p><p>本例内部 mutex/join 不变式损坏会 abort，栈展开不能对此提供恢复保证。RAII 管理正常离开作用域和 C++ 异常，不保证进程被杀、崩溃或 abort 时执行清理。</p><h3 id="part-2-borrow" tabindex="-1">C++借用get返回值可以保存多久 <a class="header-anchor" href="#part-2-borrow" aria-label="Permalink to &quot;C++借用get返回值可以保存多久 {#part-2-borrow}&quot;">​</a></h3><p>owner.get 返回借用地址，不转移所有权；只在 owner 仍拥有对象且对象没有销毁时有效。release 则移交销毁责任并清空 owner，调用方若不立即建立新拥有者就泄漏。示例只用 get 进行同步调用，没有必要 release。</p><p>scan_report 借用 stdout 的 fd，不能把这个整数再装进会 close 的第二个拥有者。RAII 对象复制会造成双重清理，所以 unique_ptr 禁止复制；移动把唯一责任转移，原拥有者变空。借用指针不会因为移动自动延长对象生存期。</p><h3 id="part-2-thread-owner" tabindex="-1">C++拥有句柄为什么仍然可能发生数据竞争 <a class="header-anchor" href="#part-2-thread-owner" aria-label="Permalink to &quot;C++拥有句柄为什么仍然可能发生数据竞争 {#part-2-thread-owner}&quot;">​</a></h3><p>unique_ptr 解决生存期和唯一销毁，不自动提供同步。一个线程调用 run，另一个线程调用 report 或 destroy，仍违反句柄协议；内部锁只保护 worker 对 total 的更新，没有覆盖公开 API 的全部状态。</p><p>当前宿主只有一个调用线程，run 同步等待两个 worker 后返回，owner 离开作用域时它们已全部 join。若未来要异步调用，必须另行保证拥有者活到任务结束，并为所有共享状态建立同步，不能仅把 unique_ptr 换成 shared_ptr 就认为线程安全。</p><h3 id="part-2-exercise" tabindex="-1">独立练习 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;独立练习 {#part-2-exercise}&quot;">​</a></h3><p>接管raw之前插入可能抛异常的日志会怎样？能否用get产生第二个unique_ptr？</p><details class="details custom-block"><summary>参考解答与检查条件</summary><p>创建已成功但没有拥有者时日志抛出会泄漏，应先立即接管。get只借用，第二个独占拥有者最终重复销毁；需要转移时使用移动。</p></details><h3 id="part-2-sources" tabindex="-1">资料与适用边界 <a class="header-anchor" href="#part-2-sources" aria-label="Permalink to &quot;资料与适用边界 {#part-2-sources}&quot;">​</a></h3><p>2026-10-17 核对 <a href="https://man7.org/linux/man-pages/man2/read.2.html" target="_blank" rel="noopener noreferrer">Linux read 手册</a>、<a href="https://man7.org/linux/man-pages/man2/write.2.html" target="_blank" rel="noopener noreferrer">write 手册</a>、<a href="https://man7.org/linux/man-pages/man2/close.2.html" target="_blank" rel="noopener noreferrer">close 的平台差异</a>、<a href="https://man7.org/linux/man-pages/man3/pthread_create.3.html" target="_blank" rel="noopener noreferrer">pthread_create</a>、<a href="https://man7.org/linux/man-pages/man3/pthread_join.3.html" target="_blank" rel="noopener noreferrer">pthread_join</a> 与 <a href="https://man7.org/linux/man-pages/man3/pthread_mutex_lock.3p.html" target="_blank" rel="noopener noreferrer">POSIX mutex 规范镜像</a>。Linux 手册中的实现差异不直接推广为 macOS 实测结果。工程由 <a href="https://cmake.org/cmake/help/v3.20/module/FindThreads.html" target="_blank" rel="noopener noreferrer">CMake FindThreads</a> 提供线程目标，构建期会检查平台需要哪些编译和链接设置。</p><p>C++ 链接与拥有关系参照 <a href="https://en.cppreference.com/w/cpp/language/language_linkage.html" target="_blank" rel="noopener noreferrer">cppreference language linkage</a>、<a href="https://en.cppreference.com/w/cpp/memory/unique_ptr.html" target="_blank" rel="noopener noreferrer">unique_ptr</a>；中文核对 <a href="https://learn.microsoft.com/zh-cn/cpp/cpp/extern-cpp?view=msvc-170" target="_blank" rel="noopener noreferrer">Microsoft extern 说明</a>，仅引用语言链接概念，不套用其 Windows 编译开关。文章采用独立组织的边界与失败推演，外链用于溯源，必要答案已在正文。</p>',42)])])}const d=a(p,[["render",o]]);export{u as __pageData,d as default};
